{"command":"node -e "
const { TrellisClient } = await import('./packages/trellis-cli/src/client.mjs');
const client = new TrellisClient({ agentId: 'test-agent' });

// 1. Create a task via CLI
console.log('--- Creating task via CLI ---');
const created = await client.createNode('calendaritem:e2e-test', 'calendaritem', {
  type: 'task', title: 'E2E test task', taskStatus: 'pending',
  startDate: '2026-02-11', allDay: true, priority: 'low', category: 'test'
});
console.log(JSON.stringify(created, null, 2));

// 2. Read it back
console.log('--- Reading it back ---');
const node = await client.getNode('calendaritem:e2e-test');
console.log('Title:', node.node.title, '| Type:', node.node['@type']);

// 3. Update it
console.log('--- Updating ---');
const updated = await client.updateNode('calendaritem:e2e-test', 'calendaritem', {
  type: 'task', title: 'E2E test task (updated)', taskStatus: 'in-progress',
  startDate: '2026-02-11', allDay: true, priority: 'high', category: 'test'
});
console.log(JSON.stringify(updated, null, 2));

// 4. Verify update
const node2 = await client.getNode('calendaritem:e2e-test');
console.log('Updated title:', node2.node.title, '| Priority:', node2.node.priority);

// 5. Delete
console.log('--- Deleting ---');
const deleted = await client.deleteNode('calendaritem:e2e-test');
console.log(JSON.stringify(deleted, null, 2));

// 6. Verify deletion
try {
  await client.getNode('calendaritem:e2e-test');
  console.log('ERROR: node should be gone');
} catch (e) {
  console.log('Correctly deleted:', e.message);
}

console.log('--- All E2E tests passed ---');
""}

