import { TrellisClient } from './packages/trellis-cli/src/client.mjs';
const c = new TrellisClient({ agentId: 'cascade' });
const ids = ['calendaritem:person-1', 'calendaritem:file-1', 'calendaritem:project-1'];
for (const id of ids) {
  const r = await c.getNode(id);
  console.log(id, '→', r.node['title'] || r.node['@type'], '| refs:', (r.node['references'] || 'none'));
}
""}

